    let i = 0;
    let j = 0;
    while (i < n && j < m) {
        if (T[i] === R[j]) {
            matched.add(i);
            i += 1;
            j += 1;
        }
        else if (at(i + 1, j) >= at(i, j + 1))
            i += 1;
        else
            j += 1;
